create extension if not exists pgcrypto;
create table if not exists public.colleges (id uuid primary key default gen_random_uuid(), name text not null, city text, state text, latitude double precision, longitude double precision, verification_radius_m integer not null default 200 check (verification_radius_m between 50 and 2000), location_required boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, college_id uuid references public.colleges(id) on delete set null, department text, course text, graduation_year integer check (graduation_year between 2020 and 2045), bio text check (char_length(bio)<=280), avatar_path text, is_verified boolean not null default false, role text not null default 'student' check (role in ('student','admin')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.student_verifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, document_path text not null, document_type text not null check (document_type in ('college_id','fee_receipt','other')), status text not null default 'pending' check (status in ('pending','approved','rejected','resubmission_required')), reviewer_id uuid references public.profiles(id), review_reason text, submitted_at timestamptz not null default now(), reviewed_at timestamptz);
create index if not exists student_verifications_user_idx on public.student_verifications(user_id,submitted_at desc);
create index if not exists student_verifications_status_idx on public.student_verifications(status);
alter table public.colleges enable row level security; alter table public.profiles enable row level security; alter table public.student_verifications enable row level security;
create policy "Authenticated users can read colleges" on public.colleges for select to authenticated using(true);
create policy "Authenticated users can read basic profiles" on public.profiles for select to authenticated using(true);
create policy "Students create their own profile" on public.profiles for insert to authenticated with check(auth.uid()=id and role='student' and is_verified=false);
create policy "Students read own verification status" on public.student_verifications for select to authenticated using(auth.uid()=user_id);
create policy "Students submit own verification" on public.student_verifications for insert to authenticated with check(auth.uid()=user_id and status='pending' and reviewer_id is null and reviewed_at is null);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('student-verification','student-verification',false,5242880,array['image/jpeg','image/png','application/pdf']) on conflict(id) do nothing;
create policy "Students upload documents to own folder" on storage.objects for insert to authenticated with check(bucket_id='student-verification' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "Students read own documents" on storage.objects for select to authenticated using(bucket_id='student-verification' and (storage.foldername(name))[1]=auth.uid()::text);
